// Three AI Vendors, Four Selection Criteria
// CANVAS_HEIGHT: 560
// Generated by scripts/build-chartjs-sim.py from scripts/sim-charts/ai-tool-selection-radar.json.
// Edit the data file and regenerate rather than editing this file by hand.

const chartData = {
    "labels": [
        "Cost Fit",
        "Data Privacy",
        "Output Quality",
        "Language Support"
    ],
    "datasets": [
        {
            "label": "Vendor A",
            "data": [
                5,
                2,
                4,
                3
            ],
            "borderColor": "#4A90D9",
            "backgroundColor": "rgba(74,144,217,0.18)",
            "borderWidth": 2
        },
        {
            "label": "Vendor B",
            "data": [
                3,
                5,
                3,
                4
            ],
            "borderColor": "#3E9E6E",
            "backgroundColor": "rgba(62,158,110,0.18)",
            "borderWidth": 2
        },
        {
            "label": "Vendor C",
            "data": [
                2,
                3,
                5,
                2
            ],
            "borderColor": "#F5A623",
            "backgroundColor": "rgba(245,166,35,0.18)",
            "borderWidth": 2
        }
    ]
};

const chartOptions = {
    "responsive": true,
    "maintainAspectRatio": false,
    "plugins": {
        "legend": {
            "position": "top",
            "align": "end",
            "labels": {
                "boxWidth": 14,
                "font": {
                    "size": 12
                }
            }
        },
        "tooltip": {
            "titleFont": {
                "size": 13
            },
            "bodyFont": {
                "size": 13
            }
        }
    },
    "scales": {
        "r": {
            "min": 0,
            "max": 5,
            "ticks": {
                "stepSize": 1,
                "font": {
                    "size": 11
                }
            },
            "pointLabels": {
                "font": {
                    "size": 13
                }
            }
        }
    }
};

const ctx = document.getElementById('chart');
const chart = new Chart(ctx, {
    type: "radar",
    data: chartData,
    options: chartOptions
});

// Checkbox controls mirror the legend, so a series can be toggled without
// knowing that clicking a legend entry does that.
document.querySelectorAll('[data-dataset]').forEach(el => {
    el.addEventListener('change', () => {
        const i = parseInt(el.dataset.dataset, 10);
        chart.setDatasetVisibility(i, el.checked);
        chart.update();
    });
    // apply the initial state declared in the data file
    const i = parseInt(el.dataset.dataset, 10);
    chart.setDatasetVisibility(i, el.checked);
});
chart.update();

// Dropdown controls call onControl, which a sim defines in its extraJs block.
document.querySelectorAll('select[data-control]').forEach(el => {
    el.addEventListener('change', () => {
        if (typeof onControl === 'function') onControl(el.dataset.control, el.value);
    });
});


// The ranked list is the whole point of this sim: the winner changes with the
// stated priority, so the ranking is recomputed rather than fixed.
const VENDOR_REASONS = {
    'Cost Fit':        {'Vendor A': 'free tier covers a small club', 'Vendor B': 'moderate monthly cost', 'Vendor C': 'priced for organisations, not clubs'},
    'Data Privacy':    {'Vendor A': 'trains on submitted data by default', 'Vendor B': 'contractual no-training guarantee', 'Vendor C': 'no-training on paid tiers only'},
    'Output Quality':  {'Vendor A': 'good drafts, occasional tone drift', 'Vendor B': 'serviceable but generic', 'Vendor C': 'consistently strong drafts'},
    'Language Support':{'Vendor A': 'strong in English only', 'Vendor B': 'broad multilingual coverage', 'Vendor C': 'limited beyond English'}
};

function renderRanking(criterion) {
    const idx = chartData.labels.indexOf(criterion);
    const rows = chartData.datasets
        .map((d, i) => ({ name: d.label, score: d.data[idx], visible: chart.isDatasetVisible(i) }))
        .filter(r => r.visible)
        .sort((a, b) => b.score - a.score);
    const box = document.getElementById('ranking');
    if (!box) return;
    box.innerHTML = '<strong>Ranked on ' + criterion + '</strong><ol>' +
        rows.map(r => '<li>' + r.name + ' - ' + r.score + '/5 <em>(' +
                 (VENDOR_REASONS[criterion][r.name] || '') + ')</em></li>').join('') +
        '</ol>';
}

function onControl(id, value) {
    if (id === 'priority') renderRanking(value);
}

// keep the ranking in step with the vendor checkboxes too
document.querySelectorAll('[data-dataset]').forEach(el =>
    el.addEventListener('change', () => {
        const sel = document.querySelector('select[data-control="priority"]');
        renderRanking(sel ? sel.value : chartData.labels[0]);
    }));

renderRanking(chartData.labels[0]);

